#include <Geode/ui/LazySprite.hpp>
#include "../config/GeoBRConfig.hpp"
#include "NewsTab.hpp"
#include "UIHelpers.hpp"
#include "../config/GeoBRConfig.hpp"
#include "../services/ApiClient.hpp"
#include "../services/NewsService.hpp"
#include <Geode/ui/LoadingSpinner.hpp>
#include <Geode/ui/TextArea.hpp>
#include <fmt/format.h>
using namespace geode::prelude;
namespace geobr {
NewsTab*NewsTab::create(CCSize s){auto r=new NewsTab;if(r->init(s)){r->autorelease();return r;}delete r;return nullptr;}
bool NewsTab::init(CCSize s){if(!CCLayer::init())return false;setContentSize(s);ignoreAnchorPointForPosition(false);setAnchorPoint({.5f,.5f});setID("news-tab");auto title=ui::makeLabel("Avisos","goldFont.fnt",.48f);title->setAnchorPoint({0,.5f});title->setPosition({8,s.height-15});addChild(title);auto menu=CCMenu::create();menu->setPosition({s.width-50,s.height-15});auto b=ui::makeTextButton("Atualizar",88,"GJ_button_01.png",this,menu_selector(NewsTab::onRefresh),.38f,25);b->setID("news-refresh-button");menu->addChild(b);addChild(menu);CCSize ls{s.width-12,s.height-38};auto bg=ui::makePanel(ls,{10,28,62},170);bg->setPosition({s.width/2,ls.height/2+2});addChild(bg);m_list=ScrollLayer::create(ls,true,true);m_list->setPosition({6,2});m_list->setID("news-scroll");m_list->m_contentLayer->setLayout(ScrollLayer::createDefaultListLayout(4));addChild(m_list);refresh();schedule(schedule_selector(NewsTab::poll),20.f);return true;}
void NewsTab::onRefresh(CCObject*){refresh();}
void NewsTab::refresh(){m_request.cancel();if(auto e=GeoBRConfig::supabaseConfigurationError();!e.empty()){showState(e,false,true);return;}showState("Carregando noticias...",true);m_request.spawn("GeoBR - noticias",NewsService::fetch(),[this](auto r){auto x=NewsService::parse(r);if(!x.success)showState(x.error,false,true);else render(x.data);});}
void NewsTab::poll(float){if(!isVisible()||m_request.isPending())return;m_request.spawn("GeoBR - atualizar noticias",NewsService::fetch(),[this](auto response){auto result=NewsService::parse(response);if(result.success)render(result.data);});}
void NewsTab::showState(std::string const&t,bool loading,bool error){if(m_state)m_state->removeFromParent();m_list->setVisible(false);m_state=CCNode::create();m_state->setContentSize(m_list->getContentSize());m_state->setAnchorPoint({.5f,.5f});m_state->setPosition(m_list->getPosition()+m_list->getContentSize()/2);auto l=ui::makeLabel(t,"bigFont.fnt",.42f,error?ccColor3B{255,150,135}:ccColor3B{255,255,255});l->limitLabelWidth(m_list->getContentWidth()-55,.42f,.25f);l->setPosition({m_state->getContentWidth()/2,m_state->getContentHeight()/2-(loading?22:0)});m_state->addChild(l);if(loading){auto sp=LoadingSpinner::create(34);sp->setPosition({m_state->getContentWidth()/2,m_state->getContentHeight()/2+20});m_state->addChild(sp);}addChild(m_state,5);}
void NewsTab::render(std::vector<NewsItem>const&v){if(m_state){m_state->removeFromParent();m_state=nullptr;}if(v.empty()){showState("Nenhuma noticia disponivel.",false);return;}m_list->setVisible(true);ui::clearScroll(m_list);for(auto const&x:v)m_list->m_contentLayer->addChild(card(x));m_list->m_contentLayer->updateLayout();m_list->scrollToTop();}
CCNode*NewsTab::card(NewsItem const&n)const{bool pic=!n.imagePath.empty();float h=pic?176:82;auto c=CCNode::create();c->setContentSize({m_list->getContentWidth()-8,h});c->setAnchorPoint({.5f,.5f});auto bg=ui::makePanel(c->getContentSize(),n.pinned?ccColor3B{42,92,142}:ccColor3B{28,60,105},235);bg->setPosition(c->getContentSize()/2);c->addChild(bg);auto title=ui::makeLabel(n.title,"bigFont.fnt",.43f,{255,226,92});title->setAnchorPoint({0,.5f});title->setPosition({10,h-14});title->limitLabelWidth(c->getContentWidth()-145,.43f,.28f);c->addChild(title);auto type=ui::makeLabel(n.typeLabel(),"bigFont.fnt",.3f,{115,226,255});type->setAnchorPoint({1,.5f});type->setPosition({c->getContentWidth()-8,h-14});c->addChild(type);if(n.isNew){auto x=ui::makeLabel("NOVO","bigFont.fnt",.29f,{95,255,106});x->setAnchorPoint({1,.5f});x->setPosition({c->getContentWidth()-75,h-14});c->addChild(x);}auto body=SimpleTextArea::create(n.description,"chatFont.fnt",.52f,c->getContentWidth()-20);body->setAnchorPoint({0,1});body->setAlignment(kCCTextAlignmentLeft);body->setWrappingMode(WrappingMode::WORD_WRAP);body->setMaxLines(2);body->setPosition({10,h-27});c->addChild(body);auto footer=ui::makeLabel(fmt::format("{}  |  {}  |  {}",n.date,n.author,n.pinned?"FIXADO":fmt::format("Prioridade {}",n.priority)),"chatFont.fnt",.48f,{190,216,255});footer->setAnchorPoint({0,.5f});footer->setPosition({10,9});footer->limitLabelWidth(c->getContentWidth()-20,.48f,.3f);c->addChild(footer);
 // Picture of the news/notice (uploaded in the admin panel), loaded from the public bucket.
 if(pic){auto img=LazySprite::create({c->getContentWidth()-24,88},true);img->setAutoResize(true);img->setPosition({c->getContentWidth()/2,68});img->loadFromUrl(GeoBRConfig::supabaseUrl()+"/storage/v1/object/public/geobr-news-images/"+n.imagePath);c->addChild(img);}
 return c;}
}
